 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # In the lower-left triangle (column < row), cells show the unmodified
    # horizontal cycle. Recover its value at each column from those samples.
    base = [None] * w
    for c in range(w):
        observed = [grid[r][c] for r in range(c + 1, h)
                    if grid[r][c] != 0]
        if observed:
            base[c] = Counter(observed).most_common(1)[0][0]

    known = [c for c, value in enumerate(base) if value is not None]
    if not known:
        return [row[:] for row in grid]

    # Infer the shortest repeating cycle that matches the revealed prefix.
    period = None
    for p in range(1, max(known) + 2):
        if all(base[c] is None or base[c % p] is None or base[c] == base[c % p]
               for c in known):
            # Require enough observed values to anchor each cycle position.
            if all(any(k % p == j for k in known) for j in range(p)):
                period = p
                break
    if period is None:
        period = max(known) + 1
    cycle = [None] * period
    for c in known:
        cycle[c % period] = base[c]
    for j in range(period):
        if cycle[j] is None:
            nearest = min(known, key=lambda k: min((j-k) % period, (k-j) % period))
            cycle[j] = base[nearest]
    base = [cycle[c % period] for c in range(w)]

    # On/above the descending diagonal the pattern is shifted one step to the
    # preceding color; below it the original cycle remains unchanged.
    colors = sorted(set(v for row in grid for v in row if v != 0))
    # The cyclic sequence order is the observed cycle, not numeric ordering.
    def predecessor(v):
        # Find v in the inferred cyclic sequence and use the prior sequence item.
        for j, x in enumerate(cycle):
            if x == v:
                return cycle[(j - 1) % period]
        return v

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            value = base[c] if c < r else predecessor(base[c])
            row.append(grid[r][c] if grid[r][c] != 0 else value)
        out.append(row)
    return out


